## Optional Chaining & Nullish Coalescing

### Optional Chaining
```js
const user = { profile: { name: 'Alice' } };
const noUser = null;

// Without optional chaining
console.log(noUser && noUser.profile && noUser.profile.name); // null

// With optional chaining
console.log(noUser?.profile?.name); // undefined (no throw)

// Method calls
const result = user?.greet?.(); // undefined if greet doesn't exist

// Array access
const first = arr?.[0];
```

### Nullish Coalescing
```js
// || problem: treats falsy values as missing
const count = 0 || 10;   // 10 — WRONG! 0 is a valid value
const name  = '' || 'Anonymous'; // 'Anonymous' — may be wrong

// ?? only triggers on null/undefined
const count2 = 0 ?? 10;   // 0 — correct
const name2  = '' ?? 'Anonymous'; // '' — correct
const val    = null ?? 'default'; // 'default'
const val2   = undefined ?? 'default'; // 'default'
```

### Combined Pattern
```js
const avatarUrl = user?.profile?.avatar ?? '/images/default-avatar.png';
const port = config?.server?.port ?? 3000;

// With optional chaining on function calls
const price = product?.getPrice?.() ?? 0;
```

### Nullish Assignment (??=)
```js
let settings = { theme: null, lang: 'en' };
settings.theme ??= 'light'; // assigns only if null/undefined
Console.log(settings.theme); // 'light'
settings.lang ??= 'tr';     // 'en' — unchanged (not null/undefined)
```

## Iterators & Iterables

### Manual Iterator
```js
function range(start, end) {
  return {
    [Symbol.iterator]() {
      let current = start;
      return {
        next() {
          if (current <= end) {
            return { value: current++, done: false };
          }
          return { value: undefined, done: true };
        },
      };
    },
  };
}

for (const n of range(1, 5)) {
  console.log(n); // 1 2 3 4 5
}

console.log([...range(1, 3)]); // [1, 2, 3]
const [a, b] = range(10, 20); // destructuring
```

### Generator Function (simpler)
```js
function* range(start, end) {
  for (let i = start; i <= end; i++) {
    yield i;
  }
}

// Infinite sequence
function* naturals() {
  let n = 1;
  while (true) yield n++;
}

const first5 = [...take(naturals(), 5)]; // [1,2,3,4,5]
```

### Async Iterable (Pagination)
```js
async function* paginate(url) {
  let nextUrl = url;
  while (nextUrl) {
    const res = await fetch(nextUrl);
    const data = await res.json();
    yield data.items;          // yield each page
    nextUrl = data.nextPage;   // undefined → stops
  }
}

for await (const page of paginate('/api/posts')) {
  renderPage(page);
}
```

## Tagged Template Literals

### Basic Tag Function
```js
function highlight(strings, ...values) {
  return strings.reduce((result, str, i) => {
    const val = values[i - 1];
    return result + (val !== undefined ? `<mark>${val}</mark>` : '') + str;
  });
}

const name = 'Alice';
const score = 95;
console.log(highlight`User ${name} scored ${score} points`);
// 'User <mark>Alice</mark> scored <mark>95</mark> points'
```

### HTML Sanitizer (XSS Prevention)
```js
function safe(strings, ...values) {
  const escape = str =>
    String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');

  return strings.reduce((out, str, i) =>
    out + escape(values[i - 1] ?? '') + str
  );
}

const userInput = '<script>alert("xss")</script>';
document.body.innerHTML = safe`<p>Hello, ${userInput}</p>`;
// <p>Hello, &lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;</p>
```

