## Symbol

### Uniqueness Guarantee
```js
const s1 = Symbol('id');
const s2 = Symbol('id');
console.log(s1 === s2); // false — always unique
```

### Non-Enumerable Property Keys
```js
const ID = Symbol('id');
const user = { name: 'Alice', [ID]: 123 };

console.log(Object.keys(user));       // ['name'] — symbol hidden
console.log(Object.getOwnPropertySymbols(user)); // [Symbol(id)]
console.log(user[ID]); // 123
```

### Well-Known Symbols
```js
// Custom iteration
class Range {
  constructor(start, end) { this.start = start; this.end = end; }
  [Symbol.iterator]() {
    let current = this.start;
    const end = this.end;
    return {
      next() {
        return current <= end
          ? { value: current++, done: false }
          : { done: true };
      },
    };
  }
}

for (const n of new Range(1, 3)) console.log(n); // 1 2 3

// Custom coercion
class Temperature {
  constructor(celsius) { this.celsius = celsius; }
  [Symbol.toPrimitive](hint) {
    if (hint === 'number') return this.celsius;
    if (hint === 'string') return `${this.celsius}°C`;
    return this.celsius;
  }
}

const t = new Temperature(22);
console.log(+t);         // 22
console.log(`Temp: ${t}`); // 'Temp: 22°C'
```

### Global Symbol Registry
```js
const s1 = Symbol.for('app.token');
const s2 = Symbol.for('app.token');
console.log(s1 === s2); // true — shared across modules
Symbol.keyFor(s1);      // 'app.token'
```

## Microtasks vs Macrotasks

### Execution Order
```js
console.log('1 - sync');

setTimeout(() => console.log('4 - macrotask'), 0);

Promise.resolve()
  .then(() => console.log('3a - microtask'))
  .then(() => console.log('3b - microtask (chained)'));

queueMicrotask(() => console.log('3c - microtask (direct)'));

console.log('2 - sync');

// Output:
// 1 - sync
// 2 - sync
// 3a - microtask
// 3b - microtask (chained)
// 3c - microtask (direct)
// 4 - macrotask
```

### Full Event Loop Round
```
[Call Stack empties]
  → drain ALL microtasks (including newly enqueued ones)
  → [optional] render frame
  → pick ONE macrotask
  → repeat
```

### Microtask Starvation Example
```js
function infinite() {
  Promise.resolve().then(infinite); // enqueues a new microtask on every run
}
infinite();
// setTimeout callbacks will NEVER run — microtask queue never empties
```

### Node.js Priority Order
```
process.nextTick callbacks
  → Promise microtasks (.then)
  → setImmediate (check phase)
  → setTimeout (timers phase)
```

### Practical: Flushing DOM updates
```js
// Schedule code after the browser has rendered
function afterFrame(fn) {
  requestAnimationFrame(() => queueMicrotask(fn));
}
```

## Advanced Generator Patterns

### Two-Way Communication
```js
function* calculator() {
  let result = 0;
  while (true) {
    const input = yield result; // pauses AND receives value
    if (input === null) break;
    result += input;
  }
  return result;
}

const calc = calculator();
calc.next();    // start — {value: 0, done: false}
calc.next(5);   // send 5 → {value: 5, done: false}
calc.next(3);   // send 3 → {value: 8, done: false}
calc.next(null); // end → {value: 8, done: true}
```

### Lazy Pipeline (memory efficient)
```js
function* map(iterable, fn) {
  for (const item of iterable) yield fn(item);
}
function* filter(iterable, pred) {
  for (const item of iterable) if (pred(item)) yield item;
}
function* take(iterable, n) {
  let i = 0;
  for (const item of iterable) {
    if (i++ >= n) return;
    yield item;
  }
}

// Process 10 million numbers — only 5 ever in memory at once
function* range(n) { for (let i = 0; i < n; i++) yield i; }

const result = [...take(
  filter(
    map(range(10_000_000), x => x * x),
    x => x % 3 === 0
  ),
  5
)];
// [0, 9, 36, 81, 144]
```

### Redux-Saga Style
```js
function* fetchUserSaga(action) {
  try {
    const user = yield call(api.fetchUser, action.id); // async, non-blocking
    yield put(actions.userLoaded(user));               // dispatch action
  } catch (e) {
    yield put(actions.userFailed(e.message));
  }
}
```

## Reflect API

### Reflect vs Direct Object Access
```js
const obj = { x: 1 };

// Equivalent operations
obj.x;                          // direct
Reflect.get(obj, 'x');         // Reflect

'x' in obj;                     // direct
Reflect.has(obj, 'x');         // Reflect

delete obj.x;                   // direct (throws in strict on non-configurable)
Reflect.deleteProperty(obj, 'x'); // returns false instead of throwing
```

### In a Proxy Trap
```js
const handler = {
  get(target, prop, receiver) {
    console.log(`Getting: ${prop}`);
    // ✅ Use Reflect to preserve receiver (prototype chain integrity)
    return Reflect.get(target, prop, receiver);
    // ❌ Direct access loses receiver:
    // return target[prop]; // broken for inherited getters
  },
  set(target, prop, value, receiver) {
    if (typeof value !== 'string') throw new TypeError('Strings only');
    return Reflect.set(target, prop, value, receiver); // returns boolean
  },
};
```

### Reflect.ownKeys — Complete Key List
```js
const sym = Symbol('hidden');
const obj = { a: 1, [sym]: 2 };

Object.keys(obj);               // ['a']  — strings, enumerable only
Object.getOwnPropertyNames(obj); // ['a']  — strings only
Reflect.ownKeys(obj);           // ['a', Symbol(hidden)] — ALL own keys
```

### Reflect.apply — Clean Function Invocation
```js
// Old way
Function.prototype.apply.call(Math.max, null, [1, 2, 3]); // 3

// Reflect way
Reflect.apply(Math.max, null, [1, 2, 3]); // 3
```

## WebAssembly & JavaScript

### Loading a Wasm Module
```js
// Async instantiation (recommended)
const response = await fetch('/lib/image-processor.wasm');
const { instance } = await WebAssembly.instantiateStreaming(response, {
  env: {
    // Host functions Wasm can call
    log: (ptr) => console.log(readString(instance, ptr)),
  },
});

// Call Wasm exports
const result = instance.exports.compress(imagePtr, width, height, quality);
```

### Memory Model
```js
// Wasm uses a linear memory buffer — shared with JS
const memory = instance.exports.memory;
const view = new Uint8Array(memory.buffer);

// Write data to Wasm memory
const inputData = new Uint8Array([255, 0, 0, 255]); // RGBA pixel
view.set(inputData, ptr); // ptr from Wasm allocator
```

### Rust + wasm-pack Example
```rust
// lib.rs
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
pub fn fibonacci(n: u32) -> u32 {
    if n <= 1 { return n; }
    fibonacci(n - 1) + fibonacci(n - 2)
}
```

```js
// After wasm-pack build
import { fibonacci } from './pkg/my_lib.js';
console.log(fibonacci(40)); // Fast! Near-native
```

### When to Use Wasm
| Use Case | JS | Wasm |
|---|---|---|
| DOM manipulation | ✅ | ❌ (no direct access) |
| Heavy computation | Slow | Fast |
| Existing C/C++/Rust lib | Port needed | Direct compile |
| Bundle size | Smaller | Larger (.wasm file) |

## Service Workers

### Lifecycle
```
Register → Install (cache assets) → Activate (cleanup old caches) → Idle
                                                          ↕
                                                    Fetch (intercept requests)
```

### Registration
```js
// app.js
if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    const reg = await navigator.serviceWorker.register('/sw.js');
    console.log('SW registered:', reg.scope);
  });
}
```

### Service Worker Script
```js
// sw.js
const CACHE_NAME = 'app-v1';
const STATIC_ASSETS = ['/index.html', '/app.js', '/styles.css'];

// Install: pre-cache static assets
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(STATIC_ASSETS))
  );
  self.skipWaiting();
});

// Activate: clean up old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

// Fetch: cache-first for static, network-first for API
self.addEventListener('fetch', (event) => {
  const { url } = event.request;
  if (url.includes('/api/')) {
    // Network-first
    event.respondWith(
      fetch(event.request).catch(() => caches.match(event.request))
    );
  } else {
    // Cache-first
    event.respondWith(
      caches.match(event.request).then(cached => cached ?? fetch(event.request))
    );
  }
});
```

## JavaScript Performance Optimisations

### 1. Avoid Layout Thrashing
```js
// ❌ Interleaved read/write causes multiple reflows
elements.forEach(el => {
  const height = el.offsetHeight; // read → forces layout
  el.style.height = height * 2 + 'px'; // write → invalidates layout
});

// ✅ Batch reads, then writes
const heights = elements.map(el => el.offsetHeight); // all reads
elements.forEach((el, i) => { el.style.height = heights[i] * 2 + 'px'; });
```

### 2. Efficient Data Structures
```js
// ❌ O(n) lookup
const users = [{ id: 1 }, { id: 2 }, ...];
const user = users.find(u => u.id === targetId); // scans every item

// ✅ O(1) lookup
const usersById = new Map(users.map(u => [u.id, u]));
const user = usersById.get(targetId); // instant
```

### 3. Virtual Lists
```jsx
import { FixedSizeList } from 'react-window';

// Only renders visible rows — 10,000 items, ~10 DOM nodes
<FixedSizeList
  height={600}
  itemCount={10000}
  itemSize={50}
>
  {({ index, style }) => (
    <div style={style}>Row {index}</div>
  )}
</FixedSizeList>
```

### 4. Code Splitting
```js
// Dynamic import — loads only when needed
const AdminDashboard = lazy(() => import('./AdminDashboard'));

// In Next.js App Router — automatic per-route
// Each page.tsx is a separate chunk
```

### 5. requestAnimationFrame for Animations
```js
// ❌ setInterval — not synced to display refresh
setInterval(updatePosition, 16);

// ✅ rAF — runs before each paint, 60fps sync
function animate(timestamp) {
  updatePosition(timestamp);
  requestAnimationFrame(animate);
}
requestAnimationFrame(animate);
```

## WeakRef & FinalizationRegistry

### WeakRef
```js
let cache = new Map();

function getOrCreate(key, factory) {
  const ref = cache.get(key);
  const existing = ref?.deref(); // undefined if GC'd

  if (existing !== undefined) {
    return existing; // still alive — reuse
  }

  const newObj = factory();
  cache.set(key, new WeakRef(newObj)); // weak reference
  return newObj;
}

// Usage
const widget = getOrCreate('header', () => new Widget());
// Widget can be GC'd if no other references exist
```

### FinalizationRegistry
```js
const registry = new FinalizationRegistry((heldValue) => {
  // Called after the registered object is GC'd
  console.log(`${heldValue} was garbage collected`);
  cleanupExternalResource(heldValue);
});

let obj = { data: 'important' };
registry.register(obj, 'my-object'); // register with a cleanup token

obj = null; // eligible for GC
// Sometime later: 'my-object was garbage collected'
```

### Important Caveats
```js
// ❌ Never rely on this for program correctness
// GC may not run, may run late, or may run differently per browser

// ✅ Only use for:
// - Caches where stale data is acceptable
// - Releasing external (non-JS) resources
// - Debugging/profiling
```

## V8 Hidden Classes & Inline Caching

### Hidden Classes
```js
// ✅ Same hidden class — optimised
function createPoint(x, y) {
  return { x, y }; // always same property order
}
const p1 = createPoint(0, 0); // shape: {x, y}
const p2 = createPoint(1, 2); // same shape: {x, y} → shared optimised code

// ❌ Different hidden classes — deoptimised
const a = { x: 0, y: 0 };
const b = { y: 0, x: 0 }; // different insertion order → different shape!

// ❌ Dynamic property addition breaks shape
const obj = {};
obj.x = 1; // shape C0 → C1
obj.y = 2; // shape C1 → C2
// Each addition creates a new hidden class transition
```

### Inline Caching
```js
// Hot function called 10,000 times
function getX(obj) {
  return obj.x; // V8 caches the offset of 'x' for this hidden class
}

// Monomorphic (one shape) — FAST
getX({ x: 1, y: 2 }); // called many times with same shape

// Megamorphic (many shapes) — SLOW — cache thrashes
getX({ x: 1 });
getX({ x: 1, y: 2 });
getX({ x: 1, y: 2, z: 3 });
```

### Practical Rules
```js
// ✅ Initialise all properties in constructor
class Particle {
  constructor(x, y, vx, vy) {
    this.x = x; this.y = y;
    this.vx = vx; this.vy = vy; // all properties upfront = stable shape
  }
}

// ❌ Conditional properties create multiple shapes
class Bad {
  constructor(x, y, hasVelocity) {
    this.x = x; this.y = y;
    if (hasVelocity) { this.vx = 0; this.vy = 0; } // shape fork!
  }
}

// ❌ Avoid delete — deoptimises aggressively
delete obj.prop; // creates new hidden class, marks as 'dictionary mode'
```

## Temporal API

### Problems with Date
```js
new Date(2026, 0, 1); // ❌ Month is 0-indexed! January = 0
new Date('2026-01-01'); // ❌ Parsed as UTC, displayed in local time — confusing
const d = new Date();
d.setMonth(d.getMonth() + 1); // ❌ Mutates! Side-effecting
```

### Temporal Basics
```js
import { Temporal } from '@js-temporal/polyfill';

// Plain date (no time, no timezone)
const date = Temporal.PlainDate.from('2026-05-22');
console.log(date.year);  // 2026
console.log(date.month); // 5  — 1-indexed!
console.log(date.day);   // 22

// Add duration — immutable!
const nextMonth = date.add({ months: 1 });
console.log(nextMonth.toString()); // '2026-06-22'
console.log(date.toString());      // '2026-05-22' — unchanged
```

### ZonedDateTime — Full Timezone Awareness
```js
const meeting = Temporal.ZonedDateTime.from({
  year: 2026, month: 5, day: 22,
  hour: 14, minute: 0,
  timeZone: 'Europe/London',
});

// Convert to another timezone
const inTurkey = meeting.withTimeZone('Europe/Istanbul');
console.log(inTurkey.toString());
// '2026-05-22T16:00:00+03:00[Europe/Istanbul]'
```

### Duration Arithmetic
```js
const start = Temporal.PlainDate.from('2026-01-15');
const end   = Temporal.PlainDate.from('2026-05-22');

const diff = start.until(end);
console.log(diff.toString()); // 'P127D' (127 days)
console.log(diff.total({ unit: 'weeks' })); // 18.14...
```

### Temporal vs Date
| Feature | Date | Temporal |
|---|---|---|
| Month indexing | 0-based | 1-based |
| Immutability | No | Yes |
| Time zone | Limited | First-class |
| Duration | Manual | Built-in |
| Parsing | Ambiguous | ISO 8601 strict |
